/* ---------- Tokens ---------- */
:root {
  --bg: #0b0b0d;
  --bg-2: #111114;
  --bg-3: #16161a;
  --surface: #1b1b20;
  --surface-2: #22222a;
  --line: #2a2a32;
  --line-soft: #20202a;
  --text: #ececf1;
  --text-2: #b3b3bf;
  --muted: #74747f;
  --accent: #d8b27a;       /* warm champagne */
  --accent-2: #f0d8a8;
  --danger: #e06b6b;
  --good: #7cd4a0;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow: 0 30px 60px -30px rgba(0,0,0,.7), 0 8px 24px -12px rgba(0,0,0,.6);
  --easing: cubic-bezier(.2,.7,.2,1);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; cursor: pointer; background: none; border: 0; }

h1, h2, h3, h4, h5 {
  font-family: 'Fraunces', 'Inter', serif;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.1;
  margin: 0 0 .5em;
}
h2 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); }
h3 { font-size: 1.4rem; }
h4 { font-size: 1.05rem; font-family: 'Inter', sans-serif; font-weight: 600; letter-spacing: -.005em; }

.container { width: 100%; max-width: 1320px; margin: 0 auto; padding: 0 28px; }

/* ---------- Announcement ---------- */
.announcement {
  background: linear-gradient(90deg, #0a0a0c, #15151a, #0a0a0c);
  border-bottom: 1px solid var(--line-soft);
  overflow: hidden;
  font-size: .78rem;
  color: var(--text-2);
  letter-spacing: .12em;
  text-transform: uppercase;
}
.announcement-track {
  display: inline-flex;
  gap: 28px;
  white-space: nowrap;
  padding: 10px 0;
  animation: marquee 40s linear infinite;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11,11,13,.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line-soft);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  height: 72px;
}
.nav-left { display: flex; gap: 28px; }
.nav-link {
  font-size: .9rem;
  color: var(--text-2);
  position: relative;
  padding: 6px 0;
  transition: color .25s var(--easing);
}
.nav-link::after {
  content: '';
  position: absolute; left: 0; bottom: 0;
  height: 1px; width: 0;
  background: var(--accent);
  transition: width .35s var(--easing);
}
.nav-link:hover { color: var(--text); }
.nav-link:hover::after { width: 100%; }

.brand { justify-self: center; }
.brand-mark {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: 1.4rem;
  letter-spacing: .25em;
  display: inline-flex;
  align-items: center;
}
.brand-mark .dot {
  font-size: .55em;
  margin: 0 1px;
  color: var(--accent);
  transform: translateY(-1px);
}
.brand-mark.big { font-size: 1.8rem; }

.nav-right { display: flex; gap: 6px; justify-self: end; align-items: center; }
.icon-btn {
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--text-2);
  position: relative;
  transition: background .25s var(--easing), color .25s var(--easing);
}
.icon-btn svg { width: 20px; height: 20px; }
.icon-btn:hover { background: var(--surface); color: var(--text); }
.cart-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #1a1a1f;
  font-size: 10px;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 4px;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 26px;
  border-radius: 999px;
  font-size: .92rem;
  font-weight: 500;
  letter-spacing: .02em;
  transition: transform .25s var(--easing), background .25s var(--easing), color .25s var(--easing), box-shadow .25s var(--easing);
  white-space: nowrap;
}
.btn-sm { padding: 10px 20px; font-size: .85rem; }
.btn-primary {
  background: var(--accent);
  color: #16161a;
}
.btn-primary:hover {
  background: var(--accent-2);
  transform: translateY(-1px);
  box-shadow: 0 12px 30px -12px rgba(216,178,122,.6);
}
.btn-ghost {
  color: var(--text);
  border: 1px solid var(--line);
}
.btn-ghost:hover { background: var(--surface); border-color: #3a3a45; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 80px 0 100px;
}
.hero-bg {
  position: absolute; inset: 0;
  background-image: url('https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=2000&q=85');
  background-size: cover;
  background-position: center 30%;
  filter: grayscale(.25) brightness(.55) contrast(1.05);
  transform: scale(1.05);
  animation: heroZoom 18s ease-out forwards;
}
@keyframes heroZoom { to { transform: scale(1); } }
.hero-gradient {
  position: absolute; inset: 0;
  background:
    radial-gradient(60% 60% at 20% 40%, rgba(216,178,122,.08), transparent 60%),
    linear-gradient(180deg, rgba(11,11,13,.4) 0%, rgba(11,11,13,.85) 90%),
    linear-gradient(90deg, rgba(11,11,13,.85) 0%, rgba(11,11,13,.1) 60%);
}
.hero-inner { position: relative; max-width: 760px; }
.hero-eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: .78rem; letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--text-2);
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(22,22,26,.5);
  backdrop-filter: blur(8px);
  margin-bottom: 28px;
}
.pulse {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0 rgba(216,178,122,.6);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(216,178,122,.6); }
  70% { box-shadow: 0 0 0 10px rgba(216,178,122,0); }
  100% { box-shadow: 0 0 0 0 rgba(216,178,122,0); }
}
.hero-title {
  font-size: clamp(2.4rem, 6vw, 4.8rem);
  font-weight: 400;
  letter-spacing: -.02em;
  line-height: 1.02;
  margin-bottom: .4em;
}
.hero-title em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero-sub {
  font-size: 1.05rem;
  color: var(--text-2);
  max-width: 540px;
  margin: 0 0 36px;
}
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
.hero-meta {
  display: flex; gap: 48px;
  padding-top: 28px;
  border-top: 1px solid var(--line-soft);
}
.hero-meta div { display: flex; flex-direction: column; }
.hero-meta strong { font-family: 'Fraunces', serif; font-size: 1.6rem; font-weight: 500; }
.hero-meta span { font-size: .78rem; letter-spacing: .15em; text-transform: uppercase; color: var(--muted); margin-top: 4px; }
.hero-scroll {
  position: absolute;
  bottom: 32px; right: 40px;
  font-size: .75rem;
  letter-spacing: .25em;
  text-transform: uppercase;
  color: var(--text-2);
  display: flex; align-items: center; gap: 8px;
}
.hero-scroll span { animation: bounce 2s infinite; }
@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(4px); }
}

/* ---------- Section heads ---------- */
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.section-head h2 { margin: 0; }
.kicker {
  display: inline-block;
  font-size: .72rem;
  letter-spacing: .25em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
}
.kicker-accent { color: var(--accent); }
.section-link {
  font-size: .9rem;
  color: var(--text-2);
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
  transition: color .25s, border-color .25s;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* ---------- Categories ---------- */
.categories { padding: 100px 0 40px; }
.category-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--surface);
  cursor: pointer;
  transition: transform .4s var(--easing);
}
.cat-card:hover { transform: translateY(-4px); }
.cat-card .cat-img {
  position: absolute; inset: 0;
  background-size: cover;
  background-position: center;
  filter: grayscale(.3) brightness(.7);
  transition: transform .8s var(--easing), filter .4s var(--easing);
}
.cat-card:hover .cat-img { transform: scale(1.08); filter: grayscale(0) brightness(.85); }
.cat-card::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,.85) 100%);
}
.cat-card .cat-label {
  position: absolute;
  left: 18px; bottom: 16px;
  z-index: 2;
  font-family: 'Fraunces', serif;
  font-size: 1.15rem;
  font-weight: 500;
}
.cat-card .cat-count {
  position: absolute;
  right: 16px; top: 14px;
  z-index: 2;
  font-size: .72rem;
  letter-spacing: .15em;
  color: var(--text-2);
  background: rgba(11,11,13,.55);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 999px;
  padding: 4px 10px;
  backdrop-filter: blur(6px);
}

/* ---------- Featured ---------- */
.featured { padding: 80px 0; }
.filter-tabs { display: flex; gap: 6px; padding: 4px; border: 1px solid var(--line); border-radius: 999px; }
.tab {
  padding: 8px 18px;
  font-size: .85rem;
  color: var(--text-2);
  border-radius: 999px;
  transition: background .25s, color .25s;
}
.tab:hover { color: var(--text); }
.tab.active { background: var(--surface-2); color: var(--text); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  position: relative;
  background: var(--bg-2);
  border: 1px solid var(--line-soft);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .35s var(--easing), border-color .35s var(--easing);
}
.product:hover { transform: translateY(-4px); border-color: var(--line); }
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  overflow: hidden;
  background: linear-gradient(135deg, #1c1c22, #131318);
}
.product-media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .8s var(--easing), opacity .4s var(--easing);
}
.product:hover .product-media img { transform: scale(1.05); }
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--bg);
  color: var(--text);
  font-size: .7rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
}
.product-tag.sale { background: var(--accent); color: #1a1a1f; border-color: transparent; }
.product-tag.new { background: var(--text); color: #1a1a1f; border-color: transparent; }
.product-fav {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11,11,13,.55);
  backdrop-filter: blur(6px);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--text-2);
  transition: color .25s, background .25s, transform .25s;
}
.product-fav:hover { color: #ff8a8a; background: rgba(11,11,13,.8); }
.product-fav.active { color: #ff7676; }
.product-fav svg { width: 18px; height: 18px; fill: currentColor; }

.product-add {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  padding: 11px;
  background: var(--text);
  color: #16161a;
  border-radius: 999px;
  font-size: .82rem;
  font-weight: 600;
  letter-spacing: .03em;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity .3s var(--easing), transform .3s var(--easing), background .25s;
}
.product:hover .product-add { opacity: 1; transform: translateY(0); }
.product-add:hover { background: var(--accent); }

.product-body { padding: 16px 18px 18px; }
.product-cat {
  font-size: .7rem;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--muted);
}
.product-name {
  font-family: 'Fraunces', serif;
  font-size: 1.05rem;
  font-weight: 500;
  margin: 6px 0 10px;
}
.product-price-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.product-price { font-weight: 600; }
.product-price .old { color: var(--muted); text-decoration: line-through; margin-left: 8px; font-weight: 400; }
.product-rating {
  font-size: .78rem;
  color: var(--text-2);
  display: inline-flex; align-items: center; gap: 4px;
}
.product-rating .star { color: var(--accent); }
.product-swatches { display: flex; gap: 6px; margin-top: 12px; }
.swatch {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid var(--line);
}

/* ---------- Deals ---------- */
.deals {
  padding: 100px 0;
  background:
    radial-gradient(50% 60% at 80% 30%, rgba(216,178,122,.06), transparent 70%),
    var(--bg-2);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}
.countdown {
  display: flex; gap: 8px;
}
.countdown div {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 14px;
  text-align: center;
  min-width: 64px;
  font-family: 'Fraunces', serif;
}
.countdown span { font-size: 1.4rem; font-weight: 500; display: block; }
.countdown small { font-family: 'Inter', sans-serif; font-size: .65rem; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 18px;
  min-height: 540px;
}
.deal {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 240px;
  cursor: pointer;
  transition: transform .4s var(--easing);
}
.deal:hover { transform: translateY(-3px); }
.deal-feature { grid-row: span 2; min-height: 100%; }
.deal-tall { grid-row: span 2; }
.deal-img {
  position: absolute; inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(.6);
  transition: transform .8s var(--easing), filter .4s var(--easing);
}
.deal:hover .deal-img { transform: scale(1.06); filter: brightness(.7); }
.deal::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,.85) 100%);
}
.deal-body {
  position: relative; z-index: 2;
  padding: 24px 26px 26px;
}
.deal-body h3 { font-size: clamp(1.4rem, 2.4vw, 2rem); margin-bottom: .4em; }
.deal-body h4 { margin-bottom: .3em; }
.deal-body p { color: var(--text-2); margin: 0 0 18px; max-width: 400px; }
.deal-tag {
  display: inline-block;
  background: var(--accent);
  color: #1a1a1f;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .15em;
  padding: 5px 11px;
  border-radius: 999px;
  margin-bottom: 14px;
}
.deal-link {
  display: inline-block;
  color: var(--text);
  font-size: .88rem;
  border-bottom: 1px solid rgba(255,255,255,.3);
  padding-bottom: 3px;
  transition: color .25s, border-color .25s;
}
.deal-link:hover { color: var(--accent); border-color: var(--accent); }

/* ---------- Editorial ---------- */
.editorial { padding: 100px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 18px;
  min-height: 640px;
}
.ed-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 280px;
  cursor: pointer;
  transition: transform .4s var(--easing);
}
.ed-card:hover { transform: translateY(-3px); }
.ed-large { grid-row: span 2; min-height: 100%; }
.ed-img {
  position: absolute; inset: 0;
  background-size: cover;
  background-position: center;
  filter: grayscale(.2) brightness(.65);
  transition: transform .8s var(--easing), filter .4s var(--easing);
}
.ed-card:hover .ed-img { transform: scale(1.05); filter: grayscale(0) brightness(.75); }
.ed-overlay,
.ed-card::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,.9) 100%);
}
.ed-body {
  position: relative; z-index: 2;
  padding: 24px 26px 26px;
}
.ed-meta {
  font-size: .72rem;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--text-2);
  margin-bottom: 12px;
  display: inline-block;
}
.ed-card h3 { font-size: clamp(1.3rem, 2.2vw, 1.9rem); }
.ed-card h4 { font-family: 'Fraunces', serif; font-weight: 500; font-size: 1.1rem; }
.ed-card p { color: var(--text-2); margin: 0 0 16px; max-width: 460px; }
.ed-link {
  font-size: .88rem;
  color: var(--accent);
  border-bottom: 1px solid rgba(216,178,122,.4);
  padding-bottom: 3px;
}

/* ---------- Newsletter ---------- */
.newsletter {
  padding: 100px 0;
  background:
    linear-gradient(180deg, var(--bg-2), var(--bg)),
    var(--bg);
  border-top: 1px solid var(--line-soft);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.newsletter h2 { font-size: clamp(1.8rem, 3vw, 2.6rem); }
.newsletter p { color: var(--text-2); max-width: 460px; }
.news-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.news-form input {
  flex: 1;
  min-width: 240px;
  padding: 16px 20px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  font: inherit;
  outline: none;
  transition: border-color .25s, background .25s;
}
.news-form input:focus { border-color: var(--accent); background: var(--surface-2); }
.news-form .btn { padding: 16px 28px; }
.news-msg {
  width: 100%;
  margin: 8px 0 0;
  font-size: .85rem;
  color: var(--good);
  min-height: 1.3em;
}
.news-msg.error { color: var(--danger); }

/* ---------- Footer ---------- */
.site-footer {
  padding: 80px 0 32px;
  background: #07070a;
  border-top: 1px solid var(--line-soft);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 50px;
  border-bottom: 1px solid var(--line-soft);
}
.site-footer h5 {
  font-family: 'Inter', sans-serif;
  font-size: .8rem;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--text-2);
  margin: 8px 0 18px;
  font-weight: 600;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; }
.site-footer li { margin-bottom: 10px; }
.site-footer a { color: var(--text-2); font-size: .92rem; transition: color .2s; }
.site-footer a:hover { color: var(--accent); }
.muted { color: var(--muted); font-size: .92rem; max-width: 360px; margin-top: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  padding-top: 24px;
  color: var(--muted);
  font-size: .82rem;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  bottom: 28px; left: 50%;
  transform: translate(-50%, 30px);
  background: var(--text);
  color: #16161a;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: .9rem;
  font-weight: 500;
  box-shadow: var(--shadow);
  opacity: 0;
  pointer-events: none;
  transition: opacity .35s var(--easing), transform .35s var(--easing);
  z-index: 100;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Reveal animation ---------- */
.reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity .8s var(--easing), transform .8s var(--easing);
}
.reveal.in { opacity: 1; transform: translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 1100px) {
  .category-grid { grid-template-columns: repeat(3, 1fr); }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-feature { grid-column: span 2; grid-row: auto; }
  .deal-tall { grid-row: auto; }
  .editorial-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .ed-large { grid-column: span 2; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .header-inner { grid-template-columns: auto auto auto; height: 64px; }
  .nav-left { display: none; }
  .hero { min-height: 78vh; padding: 60px 0 80px; }
  .hero-meta { gap: 28px; }
  .hero-scroll { display: none; }
  .category-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature, .deal-tall { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .ed-large { grid-column: auto; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 30px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; gap: 6px; align-items: flex-start; }
  .section-head { align-items: flex-start; }
  .filter-tabs { overflow-x: auto; max-width: 100%; }
}

