}
h2 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); }
h3 { font-size: 1.4rem; }
h4 { font-size: 1.05rem; font-family: 'Inter', sans-serif; font-weight: 600; letter-spacing: -.005em; }

.container { width: 100%; max-width: 1320px; margin: 0 auto; padding: 0 28px; }

/* ---------- Announcement ---------- */
.announcement {
  background: linear-gradient(90deg, #0a0a0c, #15151a, #0a0a0c);
  border-bottom: 1px solid var(--line-soft);
  overflow: hidden;
  font-size: .78rem;
  color: var(--text-2);
  letter-spacing: .12em;
  text-transform: uppercase;
}
.announcement-track {
  display: inline-flex;
  gap: 28px;
  white-space: nowrap;
  padding: 10px 0;
  animation: marquee 40s linear infinite;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11,11,13,.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line-soft);
