  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  padding: 11px;
  background: var(--text);
  color: #16161a;
  border-radius: 999px;
  font-size: .82rem;
  font-weight: 600;
  letter-spacing: .03em;
