+function showToast(msg) {
+  toast.textContent = msg;
+  toast.classList.add('show');
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
+}
+
+/* ---------- Countdown (resets every 24h) ---------- */
+function tick() {
+  const now = new Date();
+  const end = new Date();
+  end.setHours(23, 59, 59, 999);
+  const diff = Math.max(0, end - now);
+  const h = Math.floor(diff / 3.6e6);
+  const m = Math.floor((diff % 3.6e6) / 6e4);
+  const s = Math.floor((diff % 6e4) / 1000);
+  const pad = n => String(n).padStart(2, '0');
+  document.getElementById('cdH').textContent = pad(h);
+  document.getElementById('cdM').textContent = pad(m);
+  document.getElementById('cdS').textContent = pad(s);
+}
+tick();
+setInterval(tick, 1000);
+
+/* ---------- Newsletter ---------- */
+const newsForm = document.getElementById('newsForm');
+const newsMsg  = document.getElementById('newsMsg');
+newsForm.addEventListener('submit', e => {
+  e.preventDefault();
+  const input = newsForm.querySelector('input');
+  const email = input.value.trim();
+  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+  if (!valid) {
+    newsMsg.textContent = 'Please enter a valid email address.';
+    newsMsg.classList.add('error');
+    return;
+  }
+  newsMsg.classList.remove('error');
+  newsMsg.textContent = `Thanks — we’ll be in touch at ${email}.`;
+  input.value = '';
+});
