+/* ---------- Reveal on scroll ---------- */
+function observeReveal() {
+  const items = document.querySelectorAll('.reveal:not(.in)');
+  if (!('IntersectionObserver' in window)) {
+    items.forEach(i => i.classList.add('in')); return;
+  }
+  const io = new IntersectionObserver((entries) => {
+    entries.forEach((entry, i) => {
+      if (entry.isIntersecting) {
+        setTimeout(() => entry.target.classList.add('in'), i * 60);
+        io.unobserve(entry.target);
+      }
+    });
+  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
+  items.forEach(el => io.observe(el));
+}
+// Mark the hero & section heads as reveal-eligible too
+document.querySelectorAll('.hero-inner, .section-head, .deal, .ed-card, .newsletter-inner').forEach(el => el.classList.add('reveal'));
+observeReveal();
